(ns diplomat.version
  "GENERATED by jolt-diplomat-backend from the real Diplomat HIR.
  Do not hand-edit — see findings/milestone-5-findings.md."
  (:require [jolt.ffi :as ffi]
            [diplomat.runtime :as dr]
            [diplomat.parse-error :as parse-error]
  ))

(dr/defopaque Version "sv_Version_destroy_mv1")

(ffi/defcfn ^:private c-parse "jolt_sv_Version_parse_mv1" [:string :size_t :pointer] :void)
(ffi/defcfn ^:private c-sizeof-parse-result "jolt_sizeof_sv_Version_parse_mv1_result" [] :int)
(defn parse [text]
  (let [sz (c-sizeof-parse-result) out (ffi/alloc sz)]
    (try
      (c-parse text (count text) out)
      (dr/unwrap-result!
       (if (= 1 (ffi/read out :uint8 8))
         {:ok? true :value (->Version (ffi/read out :pointer 0) false)}
         {:ok? false :error (parse-error/->ParseError (ffi/read out :pointer 0) true)})
       "Version/parse" parse-error/message)
      (finally (ffi/free out))))
)

(ffi/defcfn ^:private c-major "sv_Version_major_mv1" [:pointer] :uint64)
(defn major [self] (c-major (:ptr self)))

(ffi/defcfn ^:private c-minor "sv_Version_minor_mv1" [:pointer] :uint64)
(defn minor [self] (c-minor (:ptr self)))

(ffi/defcfn ^:private c-patch "sv_Version_patch_mv1" [:pointer] :uint64)
(defn patch [self] (c-patch (:ptr self)))

(ffi/defcfn ^:private c-to-string "jolt_sv_Version_to_string_mv1" [:pointer :pointer] :void)
(defn to-string [self]
  (let [buf (ffi/alloc 256) w (ffi/alloc dr/writeable-struct-size)]
    (try
      (dr/simple-write! buf 256 w)
      (c-to-string (:ptr self) w)
      (let [n (ffi/read w :size_t dr/O-len)] (ffi/read-bytes buf n))
      (finally (ffi/free buf) (ffi/free w))))
)

(ffi/defcfn ^:private c-is-prerelease "sv_Version_is_prerelease_mv1" [:pointer] :int)
(defn is-prerelease [self] (c-is-prerelease (:ptr self)))

(ffi/defcfn ^:private c-pre "jolt_sv_Version_pre_mv1" [:pointer :pointer] :int)
(defn pre [self]
  (let [buf (ffi/alloc 256) w (ffi/alloc dr/writeable-struct-size)]
    (try
      (dr/simple-write! buf 256 w)
      (let [ok (c-pre (:ptr self) w)]
        (when (not= 0 ok) (let [n (ffi/read w :size_t dr/O-len)] (ffi/read-bytes buf n))))
      (finally (ffi/free buf) (ffi/free w))))
)

